import React, { useState, useCallback, useEffect } from 'react';
import classNames from 'classnames';
import { defineMessages } from 'react-intl';
import { useTranslation } from '@getvim/translate';
import Button from '../../atoms/button';
import { dateFormatter } from '../../lib';
import es from './translations/es.json';
import './index.less';

const SLOTS_PER_MINI_CARD_LIMIT = 6;

const messages = defineMessages({
  hideText: {
    defaultMessage: 'Hide',
    id: 'selectAppointmentTime.hide',
  },
  hideOffscreenText: {
    defaultMessage: 'Hide available appointments',
    id: 'selectAppointmentTime.hideOffscreenText',
  },
  showText: {
    defaultMessage: 'Show available appointments',
    id: 'selectAppointmentTime.showText',
  },
  numberOfResults: {
    defaultMessage: '{number} available',
    id: 'selectAppointmentTime.numberOfResults',
  },
  singleResult: {
    defaultMessage: '{number} available',
    id: 'selectAppointmentTime.singleResult',
  },
});

type TimeSlot = {
  startTime: string;
};

interface DayTimeSlotsProps {
  expanded?: boolean;
  slots: TimeSlot[];
  timeZone: string;
  onDayClick: (dateString: string) => any;
  dateString: string;
  selectedTimeSlots?: TimeSlot[];
  onTimeslotClick: (slot: { startTime: string }) => void;
}

function DayTimeSlots({
  expanded,
  slots,
  timeZone,
  dateString,
  onDayClick,
  onTimeslotClick,
  selectedTimeSlots,
}: DayTimeSlotsProps) {
  const intl = useTranslation({ es } as any);
  const [shouldShowAll, setShouldShowAll] = useState(false);
  const toggleShow = useCallback(() => {
    setShouldShowAll(!shouldShowAll);
  }, [setShouldShowAll, shouldShowAll]);
  const [clickedOnDayOnce, setClickedOnDayOnce] = useState(false);

  function renderNumberOfResults(numberOfTimeslots: number) {
    const resultMessage = numberOfTimeslots > 1 ? messages.numberOfResults : messages.singleResult;

    return (
      <div className="results-count text-right text-14">
        {intl.formatMessage(resultMessage, {
          number: numberOfTimeslots,
        })}
      </div>
    );
  }

  const handleDayClick = useCallback(
    (event: any) => {
      setClickedOnDayOnce(true);
      event.preventDefault();

      if (shouldShowAll) {
        toggleShow();
      }
      onDayClick(dateString);
    },
    [dateString, shouldShowAll, setClickedOnDayOnce, toggleShow, onDayClick],
  );

  const [timeslotsToDisplay, setTimeslotsToDisplay] = useState<TimeSlot[]>(
    slots.slice(0, Math.min(SLOTS_PER_MINI_CARD_LIMIT, slots.length)),
  );

  useEffect(() => {
    const newTimesSlotsToDisplay = shouldShowAll
      ? slots
      : slots.slice(0, Math.min(SLOTS_PER_MINI_CARD_LIMIT, slots.length));

    setTimeslotsToDisplay(newTimesSlotsToDisplay);
  }, [slots, shouldShowAll, setTimeslotsToDisplay]);

  const focusSlot = useCallback(
    (index: number) => {
      const slotElement = document.getElementById(`time_slot_button_${dateString}_${index}`);

      if (slotElement) {
        slotElement.focus();
      }
    },
    [dateString],
  );

  useEffect(() => {
    if (shouldShowAll) {
      focusSlot(SLOTS_PER_MINI_CARD_LIMIT);
    } else if (clickedOnDayOnce) {
      focusSlot(0);
    }
  }, [focusSlot, shouldShowAll, clickedOnDayOnce]);

  return (
    <div
      className={classNames('card rounded-card day-time-slots-card', { expanded })}
      data-id="day-group-wrap"
    >
      <button
        className="top"
        onClick={handleDayClick}
        aria-expanded={expanded}
        tabIndex={0}
        type="button"
      >
        <h2 className="date no-margin text-dark">
          <i className="icon-calendar-e text-18 i-va-fix-2 text-theme-secondary" />
          <span className="text-strong text-ultra-dark text-14">{dateString}</span>
        </h2>
        <span className="text-ultra-dark">{renderNumberOfResults(slots.length)}</span>
      </button>
      {expanded ? (
        <div>
          <div className="time-slots">
            {timeslotsToDisplay.map((slot: TimeSlot, index: number) => (
              <Button
                key={`time_slot_button_${slot?.startTime}`}
                id={`time_slot_button_${dateString}_${index}`}
                className="time-slot margin-bottom-15"
                selected={selectedTimeSlots?.includes(slot)}
                bgColor="groupOptionOutline"
                onClick={() => onTimeslotClick(slot)}
                buttonType="pill"
                width="small"
              >
                {dateFormatter.time(slot.startTime, timeZone)}
              </Button>
            ))}
          </div>
          {slots.length > SLOTS_PER_MINI_CARD_LIMIT && (
            <div className="show-all">
              <span className="border" />
              <Button
                buttonType="large"
                width="block"
                className="btn btn-inline-link"
                onClick={toggleShow as any}
              >
                <i
                  className={classNames('icon-chevron-down show-all-icon', {
                    opened: shouldShowAll,
                  })}
                />
                {shouldShowAll ? (
                  <span aria-live="polite">
                    <span aria-hidden="true">{intl.formatMessage(messages.hideText)}</span>
                    <span className="off-screen-text">
                      {intl.formatMessage(messages.hideOffscreenText)}
                    </span>
                  </span>
                ) : (
                  <span aria-live="polite">{intl.formatMessage(messages.showText)}</span>
                )}
              </Button>
            </div>
          )}
        </div>
      ) : null}
    </div>
  );
}

export default DayTimeSlots;
